import { Sparkles } from "lucide-react";
import { useTranslation } from "react-i18next";
import { cn } from "@/utils/cn";
import { formatIsoWithZone, formatRelativeTime, type DateInput } from "@/utils/formatters";

export interface AiGeneratedChipProps {
  /** Model that produced the content, e.g. "gemini-2.5-pro". */
  modelName?: string | null;
  /** When it was generated (shown relative). */
  generatedAt?: DateInput | null;
  size?: "sm" | "md";
  className?: string;
}

/**
 * Marks AI-generated content (purple ai tone + sparkle). Short form: "Keigan". With details:
 * "Generated by Keigan · gemini-2.5-pro · 2 min ago".
 */
export function AiGeneratedChip({ modelName, generatedAt, size = "md", className }: AiGeneratedChipProps) {
  const { t } = useTranslation("common");
  const hasDetails = Boolean(modelName || generatedAt);
  const detailParts = [hasDetails ? t("ai.generatedBy") : t("ai.keigan"), modelName, generatedAt ? formatRelativeTime(generatedAt) : null].filter(
    (part): part is string => Boolean(part),
  );
  return (
    <span
      title={generatedAt ? `${t("ai.aiGeneratedContent")} · ${formatIsoWithZone(generatedAt)}` : t("ai.aiGeneratedContent")}
      className={cn(
        "inline-flex max-w-full shrink-0 items-center gap-1.5 rounded-full bg-ai-soft font-medium text-ai",
        size === "md" ? "h-6 px-2.5 text-caption" : "h-5 px-2 text-micro",
        className,
      )}
    >
      <Sparkles aria-hidden="true" size={size === "md" ? 14 : 12} strokeWidth={2} className="shrink-0" />
      <span className="truncate">{detailParts.join(" · ")}</span>
    </span>
  );
}
